//! A small task tracker.

use std::env;
use std::fs;

struct Task {
    id: i64,
    title: String,
    done: bool,
    prio: u8,
}

fn find(tasks: &mut [Task], id: i64) -> Option<&mut Task> {
    tasks.iter_mut().find(|task| task.id == id)
}

/// Tasks in display order: by priority ascending, ties broken by id ascending.
fn in_order(tasks: &[Task]) -> Vec<&Task> {
    let mut ordered: Vec<&Task> = tasks.iter().collect();
    ordered.sort_by_key(|task| (task.prio, task.id));
    ordered
}

/// A priority is exactly one ASCII digit from 0 to 9.
fn parse_priority(text: &str) -> Option<u8> {
    match text.as_bytes() {
        [digit @ b'0'..=b'9'] => Some(digit - b'0'),
        _ => None,
    }
}

fn main() {
    let path = env::args().nth(1).expect("a command file");
    let text = fs::read_to_string(&path).expect("a readable command file");
    let mut tasks: Vec<Task> = Vec::new();
    let mut next_id = 1;

    for line in text.trim_end_matches('\n').split('\n') {
        if line.is_empty() {
            continue;
        }
        let (command, rest) = match line.split_once(' ') {
            Some((command, rest)) => (command, rest),
            None => (line, ""),
        };

        if command == "add" {
            tasks.push(Task { id: next_id, title: rest.to_string(), done: false, prio: 5 });
            println!("added {}", next_id);
            next_id += 1;
        } else if command == "done" {
            let id: i64 = rest.parse().expect("a task id");
            match find(&mut tasks, id) {
                None => println!("no such task {}", id),
                Some(task) => {
                    task.done = true;
                    println!("done {}", id);
                }
            }
        } else if command == "prio" {
            let (id_text, p_text) = rest.split_once(' ').unwrap_or((rest, ""));
            let id: i64 = id_text.parse().expect("a task id");
            match find(&mut tasks, id) {
                None => println!("no such task {}", id),
                Some(task) => match parse_priority(p_text) {
                    None => println!("bad priority {}", p_text),
                    Some(prio) => {
                        task.prio = prio;
                        println!("prio {} {}", id, prio);
                    }
                },
            }
        } else if command == "list" {
            if rest == "all" {
                for task in in_order(&tasks) {
                    let mark = if task.done { "x" } else { "-" };
                    println!("{} {} {}", mark, task.id, task.title);
                }
            } else {
                for task in in_order(&tasks).into_iter().filter(|task| !task.done) {
                    println!("{} {}", task.id, task.title);
                }
            }
        } else {
            println!("? {}", command);
        }
    }
}

